import{_ as i,o as a,c as s,a0 as n}from"./chunks/framework.M9bIWcU1.js";const g=JSON.parse('{"title":"Architecture & Deep-Dive","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),t={name:"architecture.md"};function r(o,e,l,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture-deep-dive" tabindex="-1">Architecture &amp; Deep-Dive <a class="header-anchor" href="#architecture-deep-dive" aria-label="Permalink to &quot;Architecture &amp; Deep-Dive&quot;">​</a></h1><p>This document details the internal design, scanning flow, and AST splicing algorithms of the <code>clcbws/laravel-integrity</code> package.</p><hr><h2 id="high-level-execution-pipeline" tabindex="-1">High-Level Execution Pipeline <a class="header-anchor" href="#high-level-execution-pipeline" aria-label="Permalink to &quot;High-Level Execution Pipeline&quot;">​</a></h2><p>The execution flow of the check engine runs as follows:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[Artisan Command] --&gt; B[FileScanner]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C{--dirty flag?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C -- Yes --&gt; D[Run git status porcelain]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C -- No --&gt; E[Recursively walk dirs]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; F[Filter paths &amp; ignores]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; G[Run Active Checks]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt; H[AST Scanning / Compile Sandboxing]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt; I[Reflection / Database Checking]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    H --&gt; J[Issue Registry]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I --&gt; J</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    J --&gt; K[BaselineManager Exclusions]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    K --&gt; L[Formatters: Console / JSON / Log]</span></span></code></pre></div><hr><h2 id="_1-static-ast-parsing-astparserengine" tabindex="-1">1. Static AST Parsing (<code>AstParserEngine</code>) <a class="header-anchor" href="#_1-static-ast-parsing-astparserengine" aria-label="Permalink to &quot;1. Static AST Parsing (\`AstParserEngine\`)&quot;">​</a></h2><p>To scan code formatting rules, facade imports, and direct environment dependencies:</p><ul><li><strong>Agility</strong>: Uses <code>nikic/php-parser</code> v5 configured to use the running host PHP version (<code>ParserFactory::createForHostVersion()</code>).</li><li><strong>Optimization</strong>: Resolves namespaces and names during traversal via <code>PhpParser\\NodeVisitor\\NameResolver</code>.</li><li><strong>Node Analysis</strong>: Leverages node attributes (<code>startFilePos</code>, <code>endFilePos</code>) to fetch exact byte boundaries within raw files.</li></ul><hr><h2 id="_2-option-b-splicing-fixer-algorithm" tabindex="-1">2. Option B Splicing Fixer Algorithm <a class="header-anchor" href="#_2-option-b-splicing-fixer-algorithm" aria-label="Permalink to &quot;2. Option B Splicing Fixer Algorithm&quot;">​</a></h2><p>All fixers (<code>StrictTypesFixer</code>, <code>FacadeImportFixer</code>, <code>UnusedImportFixer</code>) modify code files without formatting corruption by using byte-offset splicing.</p><h3 id="index-shifting-mitigation" tabindex="-1">Index Shifting Mitigation <a class="header-anchor" href="#index-shifting-mitigation" aria-label="Permalink to &quot;Index Shifting Mitigation&quot;">​</a></h3><p>When modifying file contents, adding or deleting text changes byte offsets for all subsequent characters. To prevent indexing drift:</p><ol><li>All issues identified by a check are grouped by file.</li><li>The issues are sorted by their byte-level <code>start_pos</code> in <strong>descending order</strong> (bottom-to-top / right-to-left).</li><li>Modifications are applied sequentially from bottom-to-top so that indices of subsequent modifications are preserved.</li><li>The modified content is written to a <code>.tmp</code> file, validated using <code>php -l</code>, and renamed atomically.</li></ol><hr><h2 id="_3-blade-livewire-integration" tabindex="-1">3. Blade &amp; Livewire Integration <a class="header-anchor" href="#_3-blade-livewire-integration" aria-label="Permalink to &quot;3. Blade &amp; Livewire Integration&quot;">​</a></h2><ul><li><strong><code>BladeTokenScanner</code></strong>: Converts Blade markup files to PHP strings using Laravel&#39;s native compiling mechanisms (<code>Blade::compileString()</code>), then parses the generated PHP statements to search for <code>route()</code> and <code>@include</code> calls.</li><li><strong><code>LivewireComponentMapper</code></strong>: Dynamically maps Blade views to their backing PHP component classes by: <ul><li>Performing convention casing lookups.</li><li>Scanning components for returned view names in their <code>render()</code> methods using AST parser visitors.</li></ul></li></ul>`,19)])])}const u=i(t,[["render",r]]);export{g as __pageData,u as default};
